package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.NumberIsTooLargeException;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class OpenMapRealMatrix_setEntry_TriageGen0Test {

    private OpenMapRealMatrix matrix;
    private final int rows = 5;
    private final int cols = 5;

    @Before
    public void setUp() {
        matrix = new OpenMapRealMatrix(rows, cols);
    }





    @Test
    public void testSetEntry_ZeroValue_AddsEntry() {
        int row = 2;
        int col = 2;
        // First set a non-zero value to ensure it's in the map
        matrix.setEntry(row, col, 1.0);

        // Now set to zero to trigger the removal branch
        matrix.setEntry(row, col, 0.0);

        assertEquals("Value should be 0.0 after setting to zero", 0.0, matrix.getEntry(row, col), 1e-10);
        // In OpenMapRealMatrix, setting to 0.0 removes the entry from the underlying map.
        // While we can't check the map directly without reflection, getEntry confirms the behavior.
    }










}

