package org.apache.commons.math.linear;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.NumberIsTooLargeException;
import org.apache.commons.math.util.OpenIntToDoubleHashMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class OpenMapRealMatrix_setEntry_TriageGen0Test {

    private OpenMapRealMatrix matrix;
    private final int rows = 5;
    private final int cols = 5;

    @Before
    public void setUp() {
        matrix = new OpenMapRealMatrix(rows, cols);
    }















    @Test
    public void testSetEntry_OverwriteExistingValue() {
        int row = 3;
        int col = 3;
        matrix.setEntry(row, col, 1.0);
        matrix.setEntry(row, col, 2.0);

        assertEquals("Value should be overwritten", 2.0, matrix.getEntry(row, col), 1e-10);
    }
}
